public class SqCrc {
    public static uint Calc(byte[] exe, byte[] sq5) {
        int tableRaw = 0x28F11E - 0x1A00;
        uint[] table = new uint[256];
        for (int i = 0; i < 256; i++) table[i] = BitConverter.ToUInt32(exe, tableRaw + i * 4);
