using System;
using System.IO;
using System.Text;
public class PeFinder2 {
    public static void Find(string path, string t) {
        byte[] b = File.ReadAllBytes(path);
        byte[] pat = Encoding.ASCII.GetBytes(t);
        int strRaw = -1;
        for (int i = 0x268600; i < 0x300000; i++) {
            bool m = true;
            for (int j = 0; j < pat.Length; j++) if (b[i+j] != pat[j]) { m = false; break; }
            if (m) { strRaw = i; break; }
        }
        while (strRaw > 0x268600 && b[strRaw - 1] != 0) strRaw--;
        int strRva = strRaw + 0x1A00;
        Console.WriteLine(string.Format("Found '{0}' at Raw=0x{1:X6} RVA=0x{2:X6}", t, strRaw, strRva));
        for (int i = 0x400; i < 0x253A00 - 7; i++) {
            int disp = BitConverter.ToInt32(b, i + 3);
            if ((i + 0xC00 + 7) + disp == strRva) {
                Console.WriteLine(string.Format("  Ref at Raw=0x{0:X6} (RVA=0x{1:X6})", i, i + 0xC00));
            }
        }
    }
}
